/*
 * A020686  Numbers of form 5 x^2 + 7 y^2.
 * https://oeis.org/A020686
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) = number of the form 5·x² + 7·y²; Generated by merging the
 *            monotone sequences for each fixed y: f_y(x) = 5·x² + 7·y² (x ≥
 *            0)
 * Range:     u8 n <= 11, u16 n <= 115, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* See https://oeis.org/A020686 */

#include <stdint.h>
#include <stdlib.h>

typedef struct {
    seq_t val;   /* current value 5·x² + 7·y² */
    idx_t y;     /* fixed y for this sequence */
    idx_t x;     /* current x */
} Node;

/* Sift down a node at index i in a min‑heap of size sz */
static void sift_down(int i, int sz, Node *h) {
    while (1) {
        int left  = 2 * i + 1;
        int right = left + 1;
        int smallest = i;

        if (left  < sz && h[left].val  < h[smallest].val) smallest = left;
        if (right < sz && h[right].val < h[smallest].val) smallest = right;

        if (smallest == i) break;
        Node tmp = h[i];
        h[i] = h[smallest];
        h[smallest] = tmp;
        i = smallest;
    }
}

seq_t a(idx_t n) {
    /* Minimal heap size needed:
       we keep one entry per y, starting with y = 0 … n‑1.
       For n ≤ 10000 this is tiny. */
    int heap_sz = (int)n;          /* guaranteed n ≥ 1 */
    Node *h = (Node *)malloc(heap_sz * sizeof(Node));
    if (!h) return (seq_t)0;       /* allocation error – unlikely */

    /* Initial population of the heap: f_y(0) = 7·y² */
    for (int i = 0; i < heap_sz; ++i) {
        idx_t y = (idx_t)i;
        h[i].y = y;
        h[i].x = 0;
        seq_t yy = (seq_t)y * (seq_t)y;
        h[i].val = (seq_t)7 * yy;
    }

    /* Build min‑heap */
    for (int i = (heap_sz / 2) - 1; i >= 0; --i)
        sift_down(i, heap_sz, h);

    seq_t result = 0;
    seq_t prev = (seq_t)-1;   /* guarantee first value kept */
    int count = 0;

    while (count < (int)n) {
        Node node = h[0];     /* smallest value */

        /* Output distinct values only */
        if (count == 0 || node.val != prev) {
            ++count;
            prev = node.val;
            if (count == (int)n) {
                result = node.val;
                break;
            }
        }

        /* Advance sequence for this y: compute next value */
        idx_t old_x = node.x;
        seq_t delta = (seq_t)5 * ( (seq_t)(2 * old_x + 1) ); /* 5·[(x+1)² – x²] */
        h[0].val = node.val + delta;
        h[0].x   = old_x + 1;

        sift_down(0, heap_sz, h);
    }

    free(h);
    return result;
}
